import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Arithmetic-Operators.md","filePath":"manual-en/Arithmetic-Operators.md","lastUpdated":1785684581000}'),i={name:"manual-en/Arithmetic-Operators.md"};function o(n,e,p,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h3 id="_7-4-arithmetic-operators" tabindex="-1">7.4 Arithmetic Operators <a class="header-anchor" href="#_7-4-arithmetic-operators" aria-label="Permalink to &quot;7.4 Arithmetic Operators&quot;">​</a></h3><p>The arithmetic operators take numeric operands and produce numeric results.</p><p><code>a + b</code></p><p>Yields the sum of a and b.</p><p><code>a - b</code></p><p>Subtracts b from a and yields the difference.</p><p><code>a * b</code></p><p>Yields the product of a and b. If either a or b is 0, then the result is 0, even if the other operand is missing.</p><p><code>a / b</code></p><p>Divides a by b and yields the quotient. If a is 0, then the result is 0, even if b is missing. If b is zero, the result is system-missing.</p><p><code>a ** b</code></p><p>Yields the result of raising a to the power b. If a is negative and b is not an integer, the result is system-missing. The result of <code>0**0</code> is system-missing as well.</p><p><code>- a</code></p><p>Reverses the sign of a.</p>',14)])])}const u=t(i,[["render",o]]);export{l as __pageData,u as default};
